class GSLIntegrationError(Exception):
    pass

def integrate_function(func, a, b, epsabs=1e-5, epsrel=1e-5, workspace_size=100):
    my_func = GSLFunction(func)
    workspace = gsl.gsl_integration_workspace_alloc(workspace_size)
    if not workspace:
        raise GSLIntegrationError("Failed to allocate workspace")

    result = ctypes.c_double()
    abserr = ctypes.c_double()
    try:
        status = gsl.gsl_integration_qags(my_func, a, b, epsabs, epsrel, workspace_size, ctypes.byref(workspace), ctypes.byref(result), ctypes.byref(abserr))
        if status != 0:
            raise GSLIntegrationError(f"GSL integration failed with status {status}")
    finally:
        gsl.gsl_integration_workspace_free(workspace)

    return result.value, abserr.value, workspace_size

