ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

GSLMatrix = ctypes.c_void_p

def create_gsl_matrix(np_array):
    rows = np_array.shape[0]
    cols = np_array.shape[1]
    data_type = np_array.dtype.type
    if data_type == np.float64:
        gsl_type = gsl.GSL_DOUBLE
    elif data_type == np.float32:
        gsl_type = gsl.GSL_FLOAT
    else:
        raise ValueError("Unsupported data type")
    matrix_ptr = gsl.gsl_matrix_alloc(rows, cols)
    if not matrix_ptr:
        raise MemoryError("Failed to allocate GSL matrix")
    ctypes.memmove(ctypes.addressof(gsl.gsl_matrix_data(matrix_ptr).contents), np_array.ctypes.data_as(ctypes.POINTER(data_type)), rows * cols * data_type.itemsize)
    return matrix_ptr

def copy_matrix(dest, src):
    if dest.rows != src.rows or dest.cols != src.cols:
        raise ValueError("Matrices dimensions do not match")
    result = gsl.copy_matrix(ctypes.byref(src), ctypes.byref(dest))
    if result != 0:
        raise RuntimeError(f"Failed to copy matrix: {result}")
    return result

