class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.wrapper = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.py_object))(self._wrapper)
        self.params = ctypes.py_object(self)

    def _wrapper(self, x, params):
        return self.func(x, params.contents.func)


def integrate_with_singularity(func, a, b, c):
    func_obj = GSLFunction(func)
    result = ctypes.c_double()
    abserr = ctypes.c_double()
    gsl.gsl_qc25c(byref(result), byref(abserr), func_obj.wrapper, a, b, c, func_obj.params)
    return (result.value, abserr.value, 0) if abserr.value == 0 else (None, abserr.value, -1)

