def numpy_to_gsl_matrix(np_array, gsl_matrix):
    rows, cols = np_array.shape
    for i in range(rows):
        for j in range(cols):
            gsl_matrix.data[i * cols + j] = ctypes.c_double(np_array[i, j])

def gsl_matrix_to_numpy(gsl_matrix):
    rows = gsl_matrix.size1
    cols = gsl_matrix.size2
    np_array = np.zeros((rows, cols), dtype=np.double)
    for i in range(rows):
        for j in range(cols):
            np_array[i, j] = gsl_matrix.data[i * cols + j]
    return np_array

def compute_covariance(jacobian, epsrel):
    assert isinstance(jacobian, GSLMatrix), 'Jacobian must be a GSLMatrix instance'
