def copy_matrix_gsl(source, destination):
    rows = len(source)
    cols = len(source[0])
    source_c = (ctypes.c_double * rows * cols)()
    for i in range(rows):
        for j in range(cols):
            source_c[i*cols + j] = source[i][j]
    destination_c = (ctypes.c_double * rows * cols)()
    gsl.gsl_matrix_memcpy(ctypes.byref(destination_c), ctypes.byref(source_c))
    for i in range(rows):
        for j in range(cols):
            destination[i][j] = destination_c[i*cols + j]
    return destination

