        _fields_ = ["data", "tda", "size1", "size2"]

    class gsl_vector(ctypes.Structure):
        _fields_ = ["data", "stride", "size"]

    def numpy_to_gsl_matrix(np_array):
        return gsl_matrix(data=np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), tda=A.shape[1], size1=A.shape[0], size2=A.shape[1])

