def weighted_skewness(w, data, wstride=1, stride=1):
    if len(w) != len(data):
        raise ValueError("Weight and data arrays must be of the same length")
    weights = (ctypes.c_double * len(w))(*w)
    datas = (ctypes.c_double * len(data))(*data)
    return compute_weighted_skewness(weights, wstride, datas, stride, len(data))

