class GSLSpMatrixInt:
    def __init__(self, matrix):
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        non_zero_count = sum(row.count(0) for row in matrix)
        self.matrix = gsl.gsl_spmatrix_int_alloc(self.rows, self.cols, non_zero_count)
        for i in range(self.rows):
            for j in range(self.cols):
                if matrix[i][j] != 0:
                    gsl.gsl_spmatrix_int_set(self.matrix, i, j, matrix[i][j])

    def __del__(self):
        gsl.gsl_spmatrix_int_free(self.matrix)

def find_min_max(matrix):
    gsl_matrix = GSLSpMatrixInt(matrix)
    min_val = ctypes.c_int()
    max_val = ctypes.c_int()
    gsl.gsl_spmatrix_int_minmax(gsl_matrix.matrix, ctypes.byref(min_val), ctypes.byref(max_val))
    return (min_val.value, max_val.value)

