class GSLFunction:
    def __init__(self, func):
        self.func = func

    def compute_derivative(self, x):
        h = 1e-6
        f_x_minus_h = self.func(x - h)
        f_x = self.func(x)
        derivative = (f_x - f_x_minus_h) / h
        abs_error = abs(f_x_minus_h - f_x)
        return (derivative, abs_error)

