import json
def matrix_to_gsl(mat):
    rows, cols = len(mat), len(mat[0])
    gsl_mat = gsl_matrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_mat[i][j] = mat[i][j]
    return gsl_mat

def vector_to_gsl(vec):
    size = len(vec)
    gsl_vec = gsl_vector(size)
    for i in range(size):
        gsl_vec[i] = vec[i]
    return gsl_vec

def gsl_matrix_to_list(mat, rows, cols):
    return [[mat[i][j] for j in range(cols)] for i in range(rows)]

def gsl_vector_to_list(vec, size):
    return [vec[i] for i in range(size)]

def ql_decomposition_and_unpack(A, tau):
    rows = len(A)
    cols = len(A[0])
    A_gsl = matrix_to_gsl(A)
    tau_gsl = vector_to_gsl(tau)

    q_gsl = gsl_matrix(rows, rows)
    l_gsl = gsl_matrix(rows, cols)

    gsl.gsl_linalg_QL_decomp.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_vector)]
    gsl.gsl_linalg_QL_decomp.restype = ctypes.c_int
    gsl.gsl_linalg_QL_decomp(A_gsl, tau_gsl)

    gsl.gsl_linalg_QL_unpack.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_vector), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix)]
    gsl.gsl_linalg_QL_unpack.restype = None
    gsl.gsl_linalg_QL_unpack(A_gsl, tau_gsl, q_gsl, l_gsl)

    Q = gsl_matrix_to_list(q_gsl, rows, rows)
    L = gsl_matrix_to_list(l_gsl, rows, cols)

    return json.dumps({'Q': Q, 'L': L})
