def find_minimum(func, x_minimum, x_lower, x_upper):
    func_ptr = GSLFunction(func).wrapped_func
    result = gsl.gsl_min_fminimizer_brent_new()
    gsl.gsl_min_fminimizer_set(result, func_ptr, x_minimum, x_lower, x_upper)
    status = 0
    while status == 0:
        status = gsl.gsl_min_test_interval(gsl.gsl_min_fminimizer_x_lower(result), gsl.gsl_min_fminimizer_x_upper(result), 1e-7, 1e-7)
        if status != 0:
            break
        gsl.gsl_min_fminimizer_iterate(result)
    return (gsl.gsl_min_fminimizer_x_minimum(result), gsl.gsl_function_evaluate(func_ptr, gsl.gsl_min_fminimizer_x_minimum(result))

