def find_minimum(func, x_minimum, x_lower, x_upper):
    gsl.gsl_set_error_handler_off()
    func_obj = GSLFunction(func)
    f_ptr = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(func_obj.test_func)
    result = gsl.gsl_min_fminimizer_brent_newton(f_ptr, x_minimum, x_lower, x_upper)
    if result == 0:
        minimum = gsl.gsl_vector_get(gsl.gsl_min_fminimizer_x(result), 0)
        function_value = func(minimum)
        return minimum, function_value
    else:
        raise Exception("Failed to find minimum")

