#include <gsl/gsl_multifit_nlin.h>

int solve_system(double *time_points, double *noisy_observations, int n, double *params) {
    gsl_multifit_function_fdf f;
    f.f = &model_func;
    f.df = NULL;
    f.fdf = NULL;
    f.n = n;
    f.p = 3;
    f.params = params;

    double x_init[3] = {1.0, 1.0, 1.0};
    gsl_multifit_fdfsolver *s = gsl_multifit_fdfsolver_alloc(gsl_multifit_fdfsolver_lmsder, n, 3);
    gsl_multifit_fdfsolver_set(s, &f, x_init);

    int status;
    size_t iter = 0;
    do {
        iter++;
        status = gsl_multifit_fdfsolver_iterate(s);
        if (status != GSL_SUCCESS) break;
        status = gsl_multifit_test_delta(s->dx, s->x, 1e-4, 1e-4);
    } while(status == GSL_CONTINUE && iter < 500);

    if (status == GSL_SUCCESS) {
        params[0] = s->x[0];
        params[1] = s->x[1];
        params[2] = s->x[2];
    }

    gsl_multifit_fdfsolver_free(s);
    return status;
}

int model_func(const gsl_vector *x, void *params, gsl_vector *f) {
    double a = gsl_vector_get(x, 0);
    double b = gsl_vector_get(x, 1);
    double c = gsl_vector_get(x, 2);
    const double *time_points = (const double *)params;
    const double *noisy_observations = (const double *)&time_points[n];

    for (size_t i = 0; i < n; ++i) {
        double model_value = a * time_points[i] + b * time_points[i] * time_points[i] + c;
        gsl_vector_set(f, i, model_value - noisy_observations[i]);
    }

    return GSL_SUCCESS;
}

